package com.afaq.iman;import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import android.appwidget.AppWidgetManager;import android.content.ComponentName;public class BootReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){int[] ids=AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,PrayerWidgetProvider.class));PrayerWidgetProvider.updateAll(c,ids);}}
